create table if not exists agent_marketplace_installs (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  user_id uuid not null references app_users(id) on delete cascade,
  item_id uuid not null references agent_marketplace_items(id) on delete cascade,
  target text not null check (target in ('workspace', 'desktop')),
  installed_version text not null,
  status text not null default 'installed' check (status in ('installed', 'removed')),
  metadata jsonb not null default '{}'::jsonb,
  installed_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(workspace_id, user_id, item_id, target)
);

create index if not exists agent_marketplace_installs_workspace_idx
  on agent_marketplace_installs(workspace_id, user_id, status, updated_at desc);

update agent_marketplace_items set status='hidden',updated_at=now()
where slug='mcp-reference-servers' and manifest->>'catalog'='true';

